# enumerate max rectangle of any value >= 12 cells at ranges
def max_rectangles(min_h=3,min_w=3):
 out=[]
 for r0 in range(R):
  for c0 in range(C):
   v=grid[r0][c0]
   valid=[True]*C
   for r1 in range(r0,R):
    valid=[valid[c] and grid[r1][c]==v for c in range(C)]
    c=c0
    while c<C:
     if not valid[c]: c+=1; continue
     c1=c
     while c1<C and valid[c1]: c1+=1
     if r1-r0+1>=min_h and c1-c>=min_w: out.append((r1-r0+1,c1-c,r0,c,v))
     c=c1
 return out
print(sorted([x for x in max_rectangles(3,3) if x[0]*x[1]>=12], reverse=True)[:50])

